// Super simple auth - just username/password
import { supabase } from '../lib/supabase';

// Document and Chat interfaces
export interface DocumentData {
  id: string;
  title: string;
  content: string;
  tags?: string[];
  status?: string;
  complexity?: string;
  originalTitle?: string;
  summary?: string;
  simplificationLevel?: number;
  pageCount?: number;
  fileSize?: number;
  type?: string;
  createdAt?: string;
  originalContent?: string;
  simplifiedContent?: string;
  userId?: string;
}

export interface ChatMessageData {
  id: string;
  content: string;
  sender: 'user' | 'ai';
  documentId?: string;
  createdAt?: string;
}

export interface User {
  id: string;
  email: string;
  full_name?: string;
}

// Document Service
export const documentService = {
  getAllDocuments: async (): Promise<DocumentData[]> => {
    if (!supabase) {
      console.log('📝 Using mock documents');
      return [];
    }

    try {
      const { data, error } = await supabase
        .from('documents')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        console.error('Error fetching documents:', error);
        return [];
      }

      return data?.map(doc => ({
        id: doc.id,
        title: doc.title,
        content: doc.simplified_content || doc.original_content,
        originalContent: doc.original_content,
        simplifiedContent: doc.simplified_content,
        originalTitle: doc.original_title,
        summary: doc.summary,
        complexity: doc.complexity,
        status: doc.status,
        type: doc.type,
        tags: doc.tags || [],
        simplificationLevel: doc.simplification_level,
        pageCount: doc.page_count,
        fileSize: doc.file_size,
        createdAt: doc.created_at,
        userId: doc.user_id,
      })) || [];
    } catch (error) {
      console.error('Error in getAllDocuments:', error);
      return [];
    }
  },

  getUserDocuments: async (): Promise<{ documents: DocumentData[]; error: string | null }> => {
    if (!supabase) {
      return { documents: [], error: null };
    }

    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        return { documents: [], error: 'User not authenticated' };
      }

      const { data, error } = await supabase
        .from('documents')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });

      if (error) {
        return { documents: [], error: error.message };
      }

      const documents = data?.map(doc => ({
        id: doc.id,
        title: doc.title,
        content: doc.simplified_content || doc.original_content,
        originalContent: doc.original_content,
        simplifiedContent: doc.simplified_content,
        originalTitle: doc.original_title,
        summary: doc.summary,
        complexity: doc.complexity,
        status: doc.status,
        type: doc.type,
        tags: doc.tags || [],
        simplificationLevel: doc.simplification_level,
        pageCount: doc.page_count,
        fileSize: doc.file_size,
        createdAt: doc.created_at,
        userId: doc.user_id,
      })) || [];

      return { documents, error: null };
    } catch (error) {
      return { documents: [], error: 'Failed to fetch documents' };
    }
  },

  getDocument: async (id: string): Promise<{ document: DocumentData | null; error: string | null }> => {
    if (!supabase) {
      return { document: null, error: 'Supabase not configured' };
    }

    try {
      const { data, error } = await supabase
        .from('documents')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        return { document: null, error: error.message };
      }

      const document = {
        id: data.id,
        title: data.title,
        content: data.simplified_content || data.original_content,
        originalContent: data.original_content,
        simplifiedContent: data.simplified_content,
        originalTitle: data.original_title,
        summary: data.summary,
        complexity: data.complexity,
        status: data.status,
        type: data.type,
        tags: data.tags || [],
        simplificationLevel: data.simplification_level,
        pageCount: data.page_count,
        fileSize: data.file_size,
        createdAt: data.created_at,
        userId: data.user_id,
      };

      return { document, error: null };
    } catch (error) {
      return { document: null, error: 'Failed to fetch document' };
    }
  },

  createDocument: async (documentData: Partial<DocumentData>): Promise<DocumentData | null> => {
    if (!supabase) {
      console.log('📝 Mock document creation');
      return null;
    }

    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error } = await supabase
        .from('documents')
        .insert({
          user_id: user.id,
          title: documentData.title || 'Untitled Document',
          original_content: documentData.originalContent || documentData.content || '',
          simplified_content: documentData.simplifiedContent,
          original_title: documentData.originalTitle,
          file_type: 'text/plain',
          file_size: documentData.fileSize || 0,
          summary: documentData.summary,
          complexity: documentData.complexity,
          tags: documentData.tags,
          type: documentData.type,
          status: documentData.status || 'completed',
        })
        .select()
        .single();

      if (error) {
        console.error('Error creating document:', error);
        return null;
      }

      return {
        id: data.id,
        title: data.title,
        content: data.simplified_content || data.original_content,
        originalContent: data.original_content,
        simplifiedContent: data.simplified_content,
        originalTitle: data.original_title,
        summary: data.summary,
        complexity: data.complexity,
        status: data.status,
        type: data.type,
        tags: data.tags || [],
        simplificationLevel: data.simplification_level,
        pageCount: data.page_count,
        fileSize: data.file_size,
        createdAt: data.created_at,
        userId: data.user_id,
      };
    } catch (error) {
      console.error('Error in createDocument:', error);
      return null;
    }
  },

  updateDocument: async (id: string, updates: Partial<DocumentData>): Promise<DocumentData | null> => {
    if (!supabase) {
      return null;
    }

    try {
      const { data, error } = await supabase
        .from('documents')
        .update({
          title: updates.title,
          simplified_content: updates.simplifiedContent,
          summary: updates.summary,
          complexity: updates.complexity,
          tags: updates.tags,
          status: updates.status,
          updated_at: new Date().toISOString(),
        })
        .eq('id', id)
        .select()
        .single();

      if (error) {
        console.error('Error updating document:', error);
        return null;
      }

      return {
        id: data.id,
        title: data.title,
        content: data.simplified_content || data.original_content,
        originalContent: data.original_content,
        simplifiedContent: data.simplified_content,
        originalTitle: data.original_title,
        summary: data.summary,
        complexity: data.complexity,
        status: data.status,
        type: data.type,
        tags: data.tags || [],
        simplificationLevel: data.simplification_level,
        pageCount: data.page_count,
        fileSize: data.file_size,
        createdAt: data.created_at,
        userId: data.user_id,
      };
    } catch (error) {
      console.error('Error in updateDocument:', error);
      return null;
    }
  },

  deleteDocument: async (id: string): Promise<boolean> => {
    if (!supabase) {
      return false;
    }

    try {
      const { error } = await supabase
        .from('documents')
        .delete()
        .eq('id', id);

      if (error) {
        console.error('Error deleting document:', error);
        return false;
      }

      return true;
    } catch (error) {
      console.error('Error in deleteDocument:', error);
      return false;
    }
  },
};

// Chat Service
export const chatService = {
  getMessages: async (documentId: string): Promise<ChatMessageData[]> => {
    if (!supabase) {
      return [];
    }

    try {
      const { data, error } = await supabase
        .from('chat_messages')
        .select('*')
        .eq('document_id', documentId)
        .order('created_at', { ascending: true });

      if (error) {
        console.error('Error fetching messages:', error);
        return [];
      }

      return data?.map(msg => ({
        id: msg.id,
        content: msg.content,
        sender: msg.sender,
        documentId: msg.document_id,
        createdAt: msg.created_at,
      })) || [];
    } catch (error) {
      console.error('Error in getMessages:', error);
      return [];
    }
  },

  sendMessage: async (documentId: string, content: string): Promise<ChatMessageData | null> => {
    if (!supabase) {
      return null;
    }

    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error('User not authenticated');
      }

      const { data, error } = await supabase
        .from('chat_messages')
        .insert({
          document_id: documentId,
          user_id: user.id,
          content,
          sender: 'user',
        })
        .select()
        .single();

      if (error) {
        console.error('Error sending message:', error);
        return null;
      }

      return {
        id: data.id,
        content: data.content,
        sender: data.sender,
        documentId: data.document_id,
        createdAt: data.created_at,
      };
    } catch (error) {
      console.error('Error in sendMessage:', error);
      return null;
    }
  },
};

// Legacy auth service (for backward compatibility)
export const authService = {
  signUp: async (username: string, password: string) => {
    console.log('⚠️ Legacy authService.signUp called - use AuthContext instead');
    return { success: false, error: 'Use AuthContext for authentication' };
  },

  signIn: async (username: string, password: string) => {
    console.log('⚠️ Legacy authService.signIn called - use AuthContext instead');
    return { success: false, error: 'Use AuthContext for authentication' };
  },

  getCurrentUser: () => {
    console.log('⚠️ Legacy authService.getCurrentUser called - use AuthContext instead');
    return null;
  },

  signOut: () => {
    console.log('⚠️ Legacy authService.signOut called - use AuthContext instead');
  }
};
